CustomSkillManager = {}
local this = CustomSkillManager
function this.Init()
    if not this.SkillEffect_AngleLeftRightOut then
        this.SkillEffect_AngleLeftRightOut = SkillEffect_AngleLeftRightOut()
    end
    if not this.SkillEffect_RadianOut then
        this.SkillEffect_RadianOut = SkillEffect_RadianOut()
    end
    this.RegistEvents()
    this.curTargetIds = {}
    this.curSkillId = nil

    --[[    local co, loadTextureRequest = SL:LoadAssetAsync("Effect/Scene/Eff_G_pugong_02.prefab", function(res)
            
        end)]]
end

function this.RegistEvents()
    SL:RegisterLUAEvent(LUA_EVENT_SKILLEFFECT_CUSTOM_Init, this.LUA_EVENT_SKILLEFFECT_CUSTOM_Init)
    SL:RegisterLUAEvent(LUA_EVENT_SKILLEFFECT_CUSTOM_Update, this.LUA_EVENT_SKILLEFFECT_CUSTOM_Update)
    SL:RegisterLUAEvent(LUA_EVENT_SKILLEFFECT_CUSTOM_ModelObjectLoaded, this.LUA_EVENT_SKILLEFFECT_CUSTOM_ModelObjectLoaded)
    SL:RegisterLUAEvent(LUA_EVENT_SKILLEFFECT_CUSTOM_Stop, this.LUA_EVENT_SKILLEFFECT_CUSTOM_Stop)
    SL:RegisterTrigger(LUA_TRIGGER_SKILL_GET_TARGETIDS, this.LUA_TRIGGER_SKILL_GET_TARGETIDS)
