    SL:RegisterTrigger(LUA_TRIGGER_SKILLEFFECT_NOT_PLAY_OTHER_TARGET_END, this.LUA_TRIGGER_SKILLEFFECT_NOT_PLAY_OTHER_TARGET_MOVE)
