function this:LUA_TRIGGER_ME_RELEASE_SKILL_Custom_REQ_FIGHT_PARAMS(skill, skillId, targetId, targetCoord)
    local myTargetId = nil
    if skillId then
        if skillId == this.curSkillId then
            myTargetId = 0
            for _, v in pairs(this.curTargetIds) do
                if v == targetId then
                    myTargetId = targetId
                end
            end
        end
    end
    return nil, nil, nil, myTargetId
end
function this:LUA_TRIGGER_SKILLEFFECT_NOT_PLAY_OTHER_TARGET_MOVE(role, skillId)
    if skillId then
        if skillId == this.curSkillId then
            return true
        end
    end
    return false
end
function this:LUA_TRIGGER_SKILL_GET_TARGETIDS(_, role, targetId, skill)
    if role and targetId and skill then
        local targetIds = {}
        this.curTargetIds = {}
        this.curSkillId = nil
        --table.insert(targetIds, role.data.id)
        if skill.skillEffectTbl and skill.skillEffectTbl.flyEffect[1] then
            this.curSkillId = skill.skillTbl.id
            local modelEffectTbl = SL:GetConfig("cfg_model_effect", skill.skillEffectTbl.flyEffect[1])
            if modelEffectTbl and modelEffectTbl.specialType == 11 and (modelEffectTbl.specialSubType == 1 or modelEffectTbl.specialSubType == 0) then

                local monsterData = SL:GetMetaValue(EMetaVarGetKey.GET_MONSTER_DATA_BY_ID, targetId)
                if monsterData then
                    ----测试开关
                    local IsShowEffect = false
                    ---------------------------------------测试特效--------------------------------------------------------------------                   
                    if IsShowEffect then
                        if this.timer then
                            SL:UnSchedule(this.timer)
                            this.timer = nil
                        end
                        if this.modelList then
                            for _, v in pairs(this.modelList) do
                                if v.model then
                                    SL:RecycleSceneItemModel(v.model)
                                end
                            end
                        end
                        this.modelList = {}
                        this.timer = {}
                        this.PlayEffectCount = 1
                    end
                    ---------------------------------------测试特效end--------------------------------------------------------------------

                    --logError("发给后端ceil.ids=|" .. monsterData.transform.position.x.."|"..monsterData.transform.position.y.."|"..monsterData.transform.position.z)
                    for index, v in pairs(skill.skillEffectTbl.flyEffect) do
                        local modelEffectTblInfo = SL:GetConfig("cfg_model_effect", v)
                        local IsTargetId = false
                        local skillEffectData = {
                            forward = Vector3.zero,
                            forwardStep = Vector3.zero,
                            beginPos = Vector3.zero,
                            targetPos = Vector3.zero,
                            newTargetPos = Vector3.zero,
                            curSkillEffectPos = Vector3.zero,
                            beginOffset = { x = modelEffectTblInfo.beginOffset[1], y = modelEffectTblInfo.beginOffset[2], z = modelEffectTblInfo.beginOffset[3] },
                            endOffset = { x = modelEffectTblInfo.endOffset[1], y = modelEffectTblInfo.endOffset[2], z = modelEffectTblInfo.endOffset[3] },
                            beginPosOffset = Vector3.zero,
                            parentWorldScale = Vector3.one,
                        }

                        local beginPos, targetPos = this:GetStartAndEndPos(modelEffectTblInfo, role, monsterData, skillEffectData.endOffset, skill.skillTbl)
                        skillEffectData.beginPos = beginPos
                        skillEffectData.targetPos = targetPos
                        --logError("箭计算初始位置=|" .. skillEffectData.beginPos.x .. "|" .. skillEffectData.beginPos.y .. "|" .. skillEffectData.beginPos.z)
                        --logError("箭计算目标位置=|" .. skillEffectData.targetPos.x .. "|" .. skillEffectData.targetPos.y .. "|" .. skillEffectData.targetPos.z)
                        SpecialSkillEffectOut.GetTargetPos_LeftRightAngle(skillEffectData.newTargetPos, skillEffectData.beginPos, skillEffectData.targetPos, E_SkillEffect_AngleLeftRightOut.angle, index)
                        if skillEffectData then
                            skillEffectData.forward:CopyFromSub(skillEffectData.newTargetPos, skillEffectData.beginPos)
                            if skillEffectData.forward == Vector3.zero then
                                skillEffectData.forward:Set(role.transform:GetForward())
                            end

                            local mag = skillEffectData.forward.magnitude
                            --目标点和当前点不重合
                            if skillEffectData.newTargetPos ~= Vector3.zero and mag > 1e-6 then
                                skillEffectData.forward:SetNormalize()
                            else
                                --目标点和当前点重合时使用角色的朝向作为方向
                                local dot = EDirectionToDot2[role.data.Dir]
                                local x, z = Dot2.GetNormalizeXZ(dot)
                                skillEffectData.forward:Set(x, 0, z)
                                skillEffectData.forward:SetNormalize()
                            end
                            skillEffectData.forwardStep:CopyFrom(skillEffectData.forward)
                            skillEffectData.forwardStep:Mul(E_SkillEffect_AngleLeftRightOut.stepSeed)
                            local tempRotation = Quaternion.identity
                            local upTemp = Vector3.zero
                            upTemp:Set(0, 1, 0)
                            tempRotation:LookRotationNonAlloc(skillEffectData.forward, upTemp)
                            --skillEffectData.beginPosAdd:CopyFromAdd(skillEffectData.beginPos,skillEffectData.beginOffset)

                            for count = 1, E_SkillEffect_AngleLeftRightOut.stepMaxCount, 1 do
                                --logError("箭步进位置=|"..skillEffectData.forwardStep.x.."|"..skillEffectData.forwardStep.z)
                                skillEffectData.beginPosOffset = skillEffectData.beginPos
                                        + tempRotation * Vector3.Scale(skillEffectData.beginOffset, skillEffectData.parentWorldScale);
                                ---------------------------------------测试特效--------------------------------------------------------------------
                                if IsShowEffect then
                                    SL:CreateSceneItemModel("Effect/Scene/Eff_G_pugong_02.prefab", function(res)
                                        if not IsNil(res) then
                                            res:SetLocalRotation(tempRotation.x, tempRotation.y, tempRotation.z, tempRotation.w)
                                            res:SetLocalPosition(skillEffectData.beginPosOffset.x, skillEffectData.beginPosOffset.y, skillEffectData.beginPosOffset.z)
                                            --logError("生成箭位置=|"..skillEffectData.beginPos.x.."|"..skillEffectData.beginPos.z)
                                            this.modelList[this.PlayEffectCount] = { time = SL:GetMetaValue(EMetaVarGetKey.GetTimeStamp), model = res }
                                            this.PlayEffectCount = this.PlayEffectCount + 1
                                            this.timer = SL:Schedule(this.timer, 0, 1, -1, function()
                                                for i = this.PlayEffectCount, 1, -1 do
                                                    if this.modelList[i] and SL:GetMetaValue(EMetaVarGetKey.GetTimeStamp) - this.modelList[i].time >= 500000 then
                                                        SL:RecycleSceneItemModel(this.modelList[i].model)
                                                        this.modelList[i] = nil
                                                    end
                                                end
                                                if table.count(this.modelList) <= 0 then
                                                    this.PlayEffectCount = 1
                                                    if this.timer then
                                                        SL:UnSchedule(this.timer)
                                                        this.timer = nil
                                                    end
                                                end
                                            end, this)
                                        end
                                    end)
                                end
                                ---------------------------------------测试特效end--------------------------------------------------------------------
                                skillEffectData.beginPos:CopyFromAdd(skillEffectData.beginPos, skillEffectData.forwardStep)

                                local monsterList = SL:GetMetaValue(EMetaVarGetKey.GET_MONSTER_DATA_LIST)
                                local playerDataList = SL:GetMetaValue(EMetaVarGetKey.GET_PLAYER_DATA_LIST)
                                if monsterList and not table.isNullOrEmpty(monsterList) then
                                    for _, monster in pairs(monsterList) do
                                        local dist = this:DistanceXZ(skillEffectData.beginPosOffset, monster.pos)
                                        local RelationshipType = SL:GetERelationshipType(monster.data.id)
                                        if monster.data.serverHp > 0 and RelationshipType == ERelationshipType.Enemy and dist < E_SkillEffect_AngleLeftRightOut.range and table.count(targetIds) < table.count(skill.skillEffectTbl.flyEffect) and not IsTargetId then
                                            table.insert(targetIds, monster.data.id)
                                            table.insert(this.curTargetIds, monster.data.id)
                                            IsTargetId = true
                                            break
                                        end
                                    end
                                end
                                if playerDataList and not table.isNullOrEmpty(playerDataList) then
                                    for _, player in pairs(playerDataList) do
                                        if player.data.id ~= InfoManager.guardPetInfo.MM_ID then
                                            local RelationshipType = SL:GetERelationshipType(player.data.id)
                                            local dist = this:DistanceXZ(skillEffectData.beginPosOffset, player.pos)
                                            if player.data.serverHp > 0 and RelationshipType == ERelationshipType.Enemy and dist < E_SkillEffect_AngleLeftRightOut.range and table.count(targetIds) < table.count(skill.skillEffectTbl.flyEffect) and not IsTargetId then
                                                table.insert(targetIds, player.data.id)
                                                table.insert(this.curTargetIds, player.data.id)
                                                IsTargetId = true
                                                break
                                            end
                                        end
                                    end
                                end
                                if IsTargetId then
                                    break
                                end
                            end
                        end

                    end
                end
            end
        end
        if table.isNullOrEmpty(targetIds) then
            return nil
        end
        return targetIds
    end

end

function this:DistanceXZ(va, vb)
    return math.sqrt((va.x - vb.x) ^ 2 + (va.z - vb.z) ^ 2)
end
function this:getTableKey(data)
    local list = {}
    for i, v in pairs(data) do
        table.insert(list, i)
    end
    return list
end
function this:LUA_EVENT_SKILLEFFECT_CUSTOM_Init(temp)
    if temp and temp.skillEffect and temp.skillEffect.skillEffectCfgData and temp.skillEffect.skillEffectCfgData.modelEffectTbl then
        local modelEffectTbl = temp.skillEffect.skillEffectCfgData.modelEffectTbl
        if modelEffectTbl.specialType == 11 then
            if modelEffectTbl.specialSubType == 2 then
                this.SkillEffect_RadianOut:Init(temp.skillEffect)
                return
            end
            this.SkillEffect_AngleLeftRightOut:Init(temp.skillEffect)
        end
    end
end
