function this:GetStartAndEndPos(modelEffectTblInfo, startRole, targetRole, endOffset, skillTbl)
    --local modelEffectTblInfo = SL:GetConfig("cfg_model_effect", effectId)
    local startPos = Vector3.zero
    local endPos = Vector3.zero
    startPos:Set(0, 0, 0)
    endPos:Set(0, 0, 0)
    --local startRole = SL:GetRoleById(startId)
    --local targetRole = SL:GetRoleById(endId)
    if modelEffectTblInfo.beginPivotType == EModelEffectPosPivotType.Body then
        if startRole then
            local selfNodeTrans = startRole.model:GetModelNode('Body')
            if selfNodeTrans then
                startPos:Set(selfNodeTrans:GetPosition())
            else
                startPos:CopyFrom(self:GetTargetPos(startRole, targetRole, skillTbl))
            end
        else
            startPos:CopyFrom(self:GetTargetPos(startRole, targetRole, skillTbl))
        end
    elseif modelEffectTblInfo.beginPivotType == EModelEffectPosPivotType.Bottom then
        startPos:CopyFrom(self:GetTargetPos(startRole, targetRole, skillTbl))
    end

    if modelEffectTblInfo.endPivotType == EModelEffectPosPivotType.Body then
        if targetRole then
            local targetNodeTrans = targetRole.model:GetModelNode('Body')
            if targetNodeTrans then
                endPos:Set(targetNodeTrans:GetPosition())
            else
                endPos:CopyFrom(self:GetTargetPos(startRole, targetRole, skillTbl, true))
            end
        else
            endPos:CopyFrom(self:GetTargetPos(startRole, targetRole, skillTbl, true))
        end
    elseif modelEffectTblInfo.endPivotType == EModelEffectPosPivotType.Bottom then
        endPos:CopyFrom(self:GetTargetPos(startRole, targetRole, skillTbl, true))
    elseif modelEffectTblInfo.endPivotType == EModelEffectPosPivotType.Parallel then
        endPos:CopyFrom(self:GetTargetPos(startRole, targetRole, skillTbl, true))
        endPos:Set(endPos.x, startPos.y, endPos.z)
    end
    if #modelEffectTblInfo.endOffset >= 3 then
        endPos:CopyFromAdd(endPos, endOffset)
    end
    return startPos, endPos
end
---@return Vector3
function this:GetTargetPos(startRole, target, skillTbl, isEndPos)
    local Scene = SL:Get_G()['Scene']
    if isEndPos and skillTbl then
        if skillTbl.releaseType == 2 then
            local t = startRole.data.OldCoord + EDirectionToDot2[startRole.data.Dir]
            if not this.tileToWorldVec then
                this.tileToWorldVec = Vector3.zero
            end
            Scene.TileToWorldVec(t.x, t.z, _, this.tileToWorldVec)
            return this.tileToWorldVec
        end
    end
    local pos = nil
    if target then
        pos = target.pos
    else
        if not this.tileToWorldVec then
            this.tileToWorldVec = Vector3.zero
        end
        Scene.TileToWorldVec(target.data.OldCoord.x, target.data.OldCoord.z, _, this.tileToWorldVec)
        pos = this.tileToWorldVec
    end
    return pos
end
